CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY AUTOINCREMENT,student_code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,department TEXT NOT NULL,year TEXT NOT NULL,email TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,attendance_date TEXT NOT NULL,check_in TEXT NOT NULL,confidence REAL,liveness_score REAL,FOREIGN KEY(student_id) REFERENCES students(id),UNIQUE(student_id,attendance_date));
